import json, os, sys, copy
fx = sys.argv[1]
valid = json.load(open(os.path.join(fx, 'valid.json')))
out = os.path.join(fx, 'json'); os.makedirs(out, exist_ok=True)
cases = {}
def case(name, f=None, raw=None):
    if raw is not None:
        cases[name] = raw; return
    m = copy.deepcopy(valid); f(m); cases[name] = json.dumps(m)
def setk(k, v): return lambda m: m.__setitem__(k, v)
def route(r): return setk('routes', r)
R = lambda **kw: dict(method='GET', path='/api/orders', permission='orders:read', **kw)
case('ok_valid', lambda m: None)
case('ok_catch_all', route([dict(method='GET', path='/api/orders/files/{rest...}', permission='orders:read')]))
# Go TestParseRefusals
case('bad_module_name', setk('module', 'Orders!'))
case('unknown_field', setk('extra', 1))
case('prefix_overlap', setk('prefixes', ['/api', '/api/orders']))
case('relative_prefix', setk('prefixes', ['api/orders']))
case('dot_prefix', setk('prefixes', ['/api/../x']))
case('route_outside_prefix', route([dict(method='GET', path='/elsewhere', permission='orders:read')]))
case('route_unprotected', route([dict(method='GET', path='/api/orders')]))
case('route_public_perm', route([dict(method='GET', path='/api/orders', public=True, permission='orders:read')]))
case('route_undeclared_perm', route([dict(method='GET', path='/api/orders', permission='orders:nope')]))
case('route_bad_param', route([dict(method='GET', path='/api/orders/{Id}', permission='orders:read')]))
case('route_long_timeout', route([R(timeout='10m')]))
case('duplicate_route', route([R(), R()]))
case('method_unprotected', setk('methods', [dict(full_method='/a.b.C/D')]))
case('method_bad_name', setk('methods', [dict(full_method='a.b.C/D', public=True)]))
case('ability_undeclared', setk('abilities', [dict(action=['read'], subject=['Order'], requires='x:y')]))
case('ability_bad_operator', setk('abilities', [dict(action=['read'], subject=['Order'], conditions={'a': {'$where': '1'}}, requires='orders:read')]))
case('ability_huge_condition', setk('abilities', [dict(action=['read'], subject=['Order'], conditions={'a': 'x'*5000}, requires='orders:read')]))
case('nav_undeclared', setk('nav', [dict(title='x', path='/x', order=1, requires='a:b')]))
case('remote_wrong_entry', setk('remote', dict(entry='/m/other/mf-manifest.json', exposes=['./routes'])))
case('remote_bad_expose', setk('remote', dict(entry='/m/orders/mf-manifest.json', exposes=['./evil'])))
case('duplicate_perm', setk('permissions', [dict(resource='orders', action='read'), dict(resource='orders', action='read')]))
case('malformed_json', raw='{')
case('trailing_garbage', raw=json.dumps(valid) + ' x')
# Extras: boundaries and semantic-only failures.
case('ok_timeout_5m', route([R(timeout='5m')]))
case('timeout_301s', route([R(timeout='301s')]))
case('timeout_0ms', route([R(timeout='0ms')]))
case('ok_timeout_1ms', route([R(timeout='1ms')]))
case('timeout_hours_grammar', route([R(timeout='1h')]))
case('ok_stream_24h', setk('methods', [dict(full_method='/a.b.C/D', permission='orders:read', streaming=True, max_stream_duration='24h')]))
case('stream_25h', setk('methods', [dict(full_method='/a.b.C/D', permission='orders:read', max_stream_duration='25h')]))
case('stream_0s', setk('methods', [dict(full_method='/a.b.C/D', permission='orders:read', max_stream_duration='0s')]))
case('duplicate_method', setk('methods', [dict(full_method='/a.b.C/D', public=True), dict(full_method='/a.b.C/D', public=True)]))
case('method_undeclared_perm', setk('methods', [dict(full_method='/a.b.C/D', permission='a:b')]))
case('route_public_false_perm', route([R(public=False)]))
case('ok_route_public_false_perm', route([R(public=False)]))
case('route_public_false_only', route([dict(method='GET', path='/api/orders', public=False)]))
case('route_method_lower', route([dict(method='get', path='/api/orders', permission='orders:read')]))
case('route_catch_all_not_last', route([dict(method='GET', path='/api/orders/{rest...}/x', permission='orders:read')]))
case('route_prefix_exact', route([dict(method='GET', path='/orders-reports', public=True)]))
case('route_prefix_sibling', route([dict(method='GET', path='/api/ordersx', permission='orders:read')]))
case('route_body_max', route([R(max_body_bytes=1073741824)]))
case('route_body_over', route([R(max_body_bytes=1073741825)]))
case('route_body_negative', route([R(max_body_bytes=-1)]))
case('route_body_float_int', raw=json.dumps(valid).replace('"max_body_bytes": 65536', '"max_body_bytes": 65536.0'))
case('route_body_fraction', route([R(max_body_bytes=1.5)]))
case('route_client_address', route([R(client_address=True)]))
case('prefix_trailing_slash', setk('prefixes', ['/api/orders/']))
case('prefix_unique', setk('prefixes', ['/api/orders', '/api/orders']))
case('prefixes_empty', setk('prefixes', []))
case('prefixes_nine', setk('prefixes', ['/p%d' % i for i in range(9)]))
case('ok_prefixes_unsorted', setk('prefixes', ['/orders-reports', '/api/orders']))
case('prefix_sibling_names', setk('prefixes', ['/api/orders', '/api/orders-x', '/orders-reports']))
case('display_name_80', setk('display_name', 'é'*80))
case('display_name_81', setk('display_name', 'é'*81))
case('display_name_empty', setk('display_name', ''))
case('version_two_parts', setk('version', '1.2'))
case('module_one_char', setk('module', 'o'))
case('module_long', setk('module', 'o'*41))
case('nav_order_1001', setk('nav', [dict(title='Orders', path='/orders', order=1001, requires='orders:read')]))
case('nav_order_float', setk('nav', [dict(title='Orders', path='/orders', order=10.0, requires='orders:read')]))
case('nav_title_41', setk('nav', [dict(title='t'*41, path='/orders', order=1, requires='orders:read')]))
case('nav_missing_order', setk('nav', [dict(title='Orders', path='/orders', requires='orders:read')]))
case('ok_integrity', setk('remote', dict(entry='/m/orders/mf-manifest.json', exposes=['./routes'], integrity='sha384-abc+/=')))
case('integrity_bad', setk('remote', dict(entry='/m/orders/mf-manifest.json', exposes=['./routes'], integrity='md5-abc')))
case('exposes_empty', setk('remote', dict(entry='/m/orders/mf-manifest.json', exposes=[])))
case('ok_exposes_header', setk('remote', dict(entry='/m/orders/mf-manifest.json', exposes=['./header', './boot'])))
case('ability_action_null', setk('abilities', [dict(action=None, subject=['Order'], requires='orders:read')]))
case('ability_action_upper', setk('abilities', [dict(action=['Read'], subject=['Order'], requires='orders:read')]))
case('ok_ability_fields_reason', setk('abilities', [dict(action=['read'], subject=['Order'], fields=['a','b'], inverted=True, reason='no <&>', requires='orders:read')]))
case('ok_conditions_depth6', setk('abilities', [dict(action=['read'], subject=['Order'], conditions={'a': {'b': {'c': {'d': {'e': {'f': 1}}}}}}, requires='orders:read')]))
case('conditions_depth7', setk('abilities', [dict(action=['read'], subject=['Order'], conditions={'a': {'b': {'c': {'d': {'e': {'f': {'g': 1}}}}}}}, requires='orders:read')]))
case('ok_conditions_numbers', setk('abilities', [dict(action=['read'], subject=['Order'], conditions={'n': {'$in': [1, 2.5, 1e21, 1e-7, 123456789012345678]}, 'z<': {'$exists': True}, 'a': None}, requires='orders:read')]))
case('conditions_list_101', setk('abilities', [dict(action=['read'], subject=['Order'], conditions={'a': {'$in': list(range(101))}}, requires='orders:read')]))
case('ok_conditions_4096', setk('abilities', [dict(action=['read'], subject=['Order'], conditions={'a': 'x'*(4096-8)}, requires='orders:read')]))
case('conditions_4097', setk('abilities', [dict(action=['read'], subject=['Order'], conditions={'a': 'x'*(4096-7)}, requires='orders:read')]))
case('conditions_html_size', setk('abilities', [dict(action=['read'], subject=['Order'], conditions={'a': '<'*(4096-8)}, requires='orders:read')]))
case('ok_conditions_empty', setk('abilities', [dict(action=['read'], subject=['Order'], conditions={}, requires='orders:read')]))
case('conditions_not_object', setk('abilities', [dict(action=['read'], subject=['Order'], conditions=[1], requires='orders:read')]))
case('permission_upper', setk('permissions', [dict(resource='Orders', action='read')]))
case('permission_description_257', setk('permissions', [dict(resource='orders', action='read', description='d'*257)] + valid['permissions'][1:]))
case('ok_unicode_strings', lambda m: (m.__setitem__('display_name', 'Ordérs   <x>'), m['nav'][0].__setitem__('title', 'Örders & co')))
case('ok_duplicate_key_last_wins', raw=json.dumps(valid)[:-1] + ', "module": "orders"}')
case('duplicate_key_last_bad', raw=json.dumps(valid)[:-1] + ', "module": "BAD"}')
case('oversized', raw=json.dumps(valid) + ' ' * (256*1024))
case('top_level_array', raw='[]')
case('route_path_space', route([dict(method='GET', path='/api/orders/a b', permission='orders:read')]))
case('route_path_param_upper_name', route([dict(method='GET', path='/api/orders/{iD}', permission='orders:read')]))
case('ok_route_path_param_under', route([dict(method='GET', path='/api/orders/{order_id}', permission='orders:read')]))
case('routes_501', route([dict(method='GET', path='/api/orders/r%d' % i, permission='orders:read') for i in range(501)]))
for n, raw in cases.items():
    open(os.path.join(out, n + '.json'), 'w').write(raw)
print(len(cases))
